st.markdown("""
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@300;400;500;600;700&display=swap');
:root { color-scheme: dark; }
.stApp {
  background:
    radial-gradient(ellipse at 16% 10%, rgba(35,75,91,.25), transparent 36%),
    radial-gradient(ellipse at 84% 78%, rgba(34,53,76,.20), transparent 34%),
    linear-gradient(145deg,#05070b 0%,#080d13 48%,#05080d 100%);
  color:#e6edf4;
}
header, footer, #MainMenu {visibility:hidden;}
.block-container {max-width:1120px; padding-top:2.2rem; padding-bottom:4rem;}
h1,h2,h3,p,div {font-family:'Manrope',sans-serif;}
.brand {
  font-family:'DM Mono',monospace; letter-spacing:.38em; color:#9ad8c8;
  font-size:12px; text-transform:uppercase;
}
.hero {
  border:1px solid rgba(154,216,200,.17); border-radius:22px;
  background:linear-gradient(135deg,rgba(14,25,34,.94),rgba(7,12,19,.82));
  padding:34px 34px 30px; position:relative; overflow:hidden;
  box-shadow:0 22px 90px rgba(0,0,0,.28);
}
.hero:after {
  content:""; position:absolute; width:420px;height:420px;right:-130px;top:-230px;
  border:1px solid rgba(154,216,200,.13);border-radius:50%;
  box-shadow:0 0 0 35px rgba(154,216,200,.025),0 0 0 75px rgba(154,216,200,.02);
}
.hero h1 {font-size:clamp(38px,7vw,76px);font-weight:300;letter-spacing:.16em;margin:15px 0 5px;}
.hero p {color:#9baab7;max-width:620px;line-height:1.8;font-size:14px;}
.kicker {font-family:'DM Mono',monospace;color:#8ba8b3;font-size:10px;letter-spacing:.22em;text-transform:uppercase;}
.scene {
  margin-top:20px;border:1px solid rgba(155,185,195,.14);border-radius:18px;
  background:linear-gradient(150deg,rgba(12,20,29,.94),rgba(7,11,17,.94));
  padding:26px;min-height:300px;position:relative;overflow:hidden;
}
.scene:before {
  content:"";position:absolute;inset:0;pointer-events:none;opacity:.18;
  background:repeating-linear-gradient(0deg,transparent 0 38px,rgba(170,210,220,.05) 39px 40px);
}
.scene-title {font-size:27px;font-weight:400;letter-spacing:.04em;margin:12px 0 18px;color:#e4edf0;}
.scene-copy {color:#b4c1c9;line-height:1.9;font-size:15px;max-width:760px;}
.signal {font-family:'DM Mono',monospace;color:#9ad8c8;font-size:10px;letter-spacing:.18em;}
.rule {height:1px;background:linear-gradient(90deg,rgba(154,216,200,.45),transparent);margin:22px 0;}
.stButton>button {
  border:1px solid rgba(154,216,200,.4);border-radius:999px;
  background:rgba(20,39,46,.78);color:#d9eee8;padding:10px 24px;
  font-family:'DM Mono',monospace;letter-spacing:.1em;font-size:11px;
  transition:all .2s ease;
}
.stButton>button:hover {border-color:#9ad8c8;background:rgba(45,82,85,.45);color:white;}
.caption {color:#748591;font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.12em;}
div[data-testid="stMetric"] {background:rgba(10,18,25,.7);border:1px solid rgba(154,216,200,.1);padding:14px;border-radius:14px;}
</style>
""", unsafe_allow_html=True)

if "scene_index" not in st.session_state:
    st.session_state.scene_index = 0
if "entered" not in st.session_state:
    st.session_state.entered = False
if "visited" not in st.session_state:
    st.session_state.visited = []

def scene_for(index):
    return ARCHIVE[index % len(ARCHIVE)]

def scene_signature(record):
    raw = "|".join(str(x) for x in record)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:12].upper()

st.markdown('<div class="brand">FIELD NOTE  /  NO PUBLIC FREQUENCY</div>', unsafe_allow_html=True)
st.markdown("""
<div class="hero">
  <div class="kicker">An atmospheric experience</div>
  <h1>AFTERLIGHT</h1>
  <p>A place between the last announcement and the first light.
  No score. No timer. No instructions. Just a world that changes when you look again.</p>
</div>
""", unsafe_allow_html=True)

if not st.session_state.entered:
    st.markdown('<div class="scene"><div class="signal">ENTRY POINT // 00:00</div><div class="scene-title">The doors are already open.</div><div class="scene-copy">Beyond the threshold, a vast interior waits beneath a ceiling that cannot be seen. Somewhere inside, a signal repeats at long intervals. The air is still. The lights are not.</div><div class="rule"></div><div class="caption">TAKE YOUR TIME. NOTHING IS CHASING YOU.</div></div>', unsafe_allow_html=True)
    if st.button("ENTER THE QUIET", use_container_width=False):
        st.session_state.entered = True
        st.rerun()
else:
    record = scene_for(st.session_state.scene_index)
    number, place, obj, sound, light, detail, transition = record
    signature = scene_signature(record)
    st.markdown(f"""
    <div class="scene">
      <div class="signal">OBSERVATION {number:05d} &nbsp; // &nbsp; TRACE {signature}</div>
      <div class="scene-title">{place}</div>
      <div class="scene-copy">{light}. Near the centre stands {obj}. {sound.capitalize()}.
      {detail}</div>
      <div class="rule"></div>
      <div class="kicker">A CHANGE IN THE DISTANCE</div>
      <div class="scene-copy">{transition}</div>
    </div>
    """, unsafe_allow_html=True)
    st.markdown("<div style='height:14px'></div>", unsafe_allow_html=True)
    left, right = st.columns([1, 4])
    with left:
        if st.button("FOLLOW THE SIGNAL", use_container_width=True):
            st.session_state.visited.append(number)
            st.session_state.scene_index = (st.session_state.scene_index + 137) % len(ARCHIVE)
            st.rerun()
    with right:
        st.markdown('<div class="caption" style="padding-top:13px">NO MAP. NO SCORE. THE ENVIRONMENT KEEPS ITS OWN RECORD.</div>', unsafe_allow_html=True)

st.markdown("<div style='height:28px'></div>", unsafe_allow_html=True)
st.markdown('<div class="caption">AFTERLIGHT  /  A QUIETLY UNSETTLING PLACE  /  BUILD 01</div>', unsafe_allow_html=True)
